 if(page==='observations'||page==='records'){const list=page==='observations'?aquaticLife.filter(a=>s.observed.includes(a.id)):aquaticSamples.filter(a=>s.samples.includes(a.id)),chunk=list.slice(n*3,n*3+3);return v(page==='observations'?'My wildlife observations':'My aquatic samples',list.length?'Tap a saved record to look again.':'My records will appear as I explore.','collection',[...chunk.map(a=>go(a.icon+' '+a.name,page==='observations'?'life:'+a.id:'record:'+a.id)),...(n>0?[go('← Previous',page+':'+(n-1))]:[]),...(list.length>(n+1)*3?[go('Next →',page+':'+(n+1))]:[]),go('← My aquatic journal','collection')]);}
 if(page==='record'){const a=aquaticSamples.find(a=>a.id===id);return v(a?.name||'Sample record',a?.fact||'Explore to save a record.','collection',[go('← My samples','records:0'),back]);}
